// Player-site localisation (i18n).
//
// Target-market languages (matched to our licensed markets / currencies). English
// is the source of truth; every other language falls back to English per-key, so a
// missing translation degrades gracefully rather than showing a blank.
//
// Money tokens like {minDepW} are NOT interpolated here — they are left intact and
// resolved later by currency.ts (loc). Only variables passed explicitly to t()
// (e.g. {ccy}) are substituted, so translated strings can safely contain both.
//
// NOTE: long-form legal / T&C bodies and responsible-gambling copy are intentionally
// kept in English until they get native/professional review before launch.

export type Lang = 'en' | 'pt' | 'no' | 'fr' | 'de' | 'es' | 'fi' | 'it' | 'nl' | 'pl' | 'tr' | 'ja'

export interface LangMeta { code: Lang; label: string; native: string; flag: string }

export const LANGS: LangMeta[] = [
  { code: 'en', label: 'English', native: 'English', flag: '🇬🇧' },
  { code: 'pt', label: 'Portuguese (Brazil)', native: 'Português', flag: '🇧🇷' },
  { code: 'no', label: 'Norwegian', native: 'Norsk', flag: '🇳🇴' },
  { code: 'fr', label: 'French (Canada)', native: 'Français', flag: '🇨🇦' },
  { code: 'de', label: 'German', native: 'Deutsch', flag: '🇩🇪' },
  { code: 'es', label: 'Spanish', native: 'Español', flag: '🇪🇸' },
  { code: 'fi', label: 'Finnish', native: 'Suomi', flag: '🇫🇮' },
  { code: 'it', label: 'Italian', native: 'Italiano', flag: '🇮🇹' },
  { code: 'nl', label: 'Dutch', native: 'Nederlands', flag: '🇳🇱' },
  { code: 'pl', label: 'Polish', native: 'Polski', flag: '🇵🇱' },
  { code: 'tr', label: 'Turkish', native: 'Türkçe', flag: '🇹🇷' },
  { code: 'ja', label: 'Japanese', native: '日本語', flag: '🇯🇵' },
]

const CODES = LANGS.map(l => l.code)

